# MOH Coop Trilogy - SERVER HOST GUI ("MOH Coop Server" desktop shortcut).
#
# Hosts the HZM coop mod as a DEDICATED server (omohaaded.exe, headless) or HOST-AND-PLAY (a listen server inside your
# own game, openmohaa.exe). Every gameplay setting comes from hzm_server_settings.json, the catalogue GENERATED by
# docs/tools/gen_server_catalogue.py (docgen.py build) from the mod's cvar sweep - nothing here lists cvars by hand.
#
#   hzm_server_gui.ps1                         the window (normally via hzm_server_gui.vbs, no console)
#   hzm_server_gui.ps1 -StartProfile <profile> the window on that profile, its server started (start-with-Windows,
#                                              "open the window" choice)
#   hzm_server_gui.ps1 -Supervise <profile>    headless server supervisor: start, restart on crash, daily restart,
#                                              rotation, Discord webhook, MOTD. The GUI starts one per running profile
#                                              through WMI (bug-11282: a child of a shell dies with the shell's job).
#   -Snapshot <dir> [-SnapshotDpi 144]         QA: render every tab to PNG off-screen (never activated) and exit
#   -DryRun                                    firewall / UPnP / start-with-Windows are written to dryrun_actions.log
#                                              and never executed
#   -NoUi                                      define the functions only (dot-sourced by tests)
#
# Lives beside openmohaa.exe / omohaaded.exe (shipped by the updater, publish_release.ps1). Profiles, logs and the
# DPAPI-protected secrets (passwords, webhook) live in %LOCALAPPDATA%\MOHCoopServer. Secrets are never logged.
# Windows PowerShell 5.1 + WPF only: nothing for a player to install.
param(
    [string]$InstallRoot = $PSScriptRoot,
    [string]$DataDir = (Join-Path $env:LOCALAPPDATA "MOHCoopServer"),
    [string]$Catalogue = "",
    [string]$Supervise = "",
    [switch]$SkipUpdateOnce,      # set by a supervisor that relaunched itself after an update replaced this script
    [string]$StartProfile = "",
    [string]$Snapshot = "",
    [int]$SnapshotDpi = 96,
    [int]$SnapshotWidth = 1100,
    [int]$SnapshotHeight = 720,
    [switch]$DryRun,
    [switch]$NoUi,
    [string]$SpeedTestUrl = "https://speed.cloudflare.com/__up",
    [string]$PublicIpUrl = "https://api.ipify.org"
)
$ErrorActionPreference = "Continue"
$script:Version = "1.0.0"
$script:GuiPath = $MyInvocation.MyCommand.Path      # also right when dot-sourced (-NoUi tests)
$script:GuiDir = Split-Path -Parent $script:GuiPath
try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}

# ======================================================================================================================
# basics: folders, log (never secrets), DPAPI secrets
# ======================================================================================================================
foreach ($d in @($DataDir, (Join-Path $DataDir "profiles"), (Join-Path $DataDir "run"), (Join-Path $DataDir "logs"))) {
    if (-not (Test-Path -LiteralPath $d)) { New-Item -ItemType Directory -Force -Path $d | Out-Null }
}
$script:GuiLog = Join-Path $DataDir "gui.log"
$script:SecretWords = New-Object System.Collections.Generic.List[string]

function Write-Log([string]$msg, [string]$file = $script:GuiLog) {
    # every log line passes through the secret scrubber: a password or webhook that reaches a message is masked
    foreach ($w in $script:SecretWords) { if ($w -and $w.Length -ge 3) { $msg = $msg.Replace($w, "****") } }
    $msg = [regex]::Replace($msg, 'https://(discord|discordapp)\.com/api/webhooks/\S+', 'https://discord.com/api/webhooks/****')
    try { Add-Content -LiteralPath $file -Value ("{0:yyyy-MM-dd HH:mm:ss} {1}" -f (Get-Date), $msg) -Encoding UTF8 } catch {}
}
function Write-DryRun([string]$what) {
    Write-Log "DRY RUN - not executed: $what" (Join-Path $DataDir "dryrun_actions.log")
}

Add-Type -AssemblyName System.Security
function Protect-Text([string]$s) {
    $b = [Text.Encoding]::UTF8.GetBytes($s)
    [Convert]::ToBase64String([Security.Cryptography.ProtectedData]::Protect($b, $null, 'CurrentUser'))
}
function Unprotect-Text([string]$s) {
    try {
        $b = [Security.Cryptography.ProtectedData]::Unprotect([Convert]::FromBase64String($s), $null, 'CurrentUser')
        [Text.Encoding]::UTF8.GetString($b)
    } catch { "" }
}
function New-RandomPassword([int]$n = 20) {
    $chars = 'abcdefghijkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    $rng = [Security.Cryptography.RandomNumberGenerator]::Create()
    $bytes = New-Object byte[] $n; $rng.GetBytes($bytes)
    -join ($bytes | ForEach-Object { $chars[$_ % $chars.Length] })
}

# ======================================================================================================================
# install detection
# ======================================================================================================================
function Get-Install {
    $gs = Get-GuiSettings
    $root = if ($gs.installRoot) { $gs.installRoot } else { $InstallRoot }
    $base = $gs.basePath; $homeDir = $gs.homePath
    if (-not $base) {
        $info = Join-Path $root "install_info.txt"
        if (Test-Path -LiteralPath $info) {
            $m = Select-String -LiteralPath $info -Pattern "^GogPath=(.*)$"
            if ($m) { $base = $m.Matches[0].Groups[1].Value.Trim() }
        }
    }
    $launchArgs = ""
    $ini = Join-Path $root "updater.ini"
    if (Test-Path -LiteralPath $ini) {
        foreach ($l in Get-Content -LiteralPath $ini) { if ($l -match '^LaunchArgs=(.*)$') { $launchArgs = $Matches[1].Trim() } }
    }
    if (-not $base -and $launchArgs -match 'fs_basepath "([^"]+)"') { $base = $Matches[1] }
    if (-not $homeDir -and $launchArgs -match 'fs_homepath "([^"]+)"') { $homeDir = $Matches[1] }
    if (-not $homeDir) { $homeDir = Join-Path $root "home" }
    if (-not $base) { $base = $root }
    [pscustomobject]@{
        Root = $root; Base = $base; Home = $homeDir; LaunchArgs = $launchArgs
        Ded = Join-Path $root "omohaaded.exe"; Client = Join-Path $root "openmohaa.exe"
        Maintt = Join-Path $homeDir "maintt"; Updater = Join-Path $root "updater.ps1"
    }
}
function Get-GuiSettings {
    $p = Join-Path $DataDir "gui_settings.json"
    $o = [pscustomobject]@{ installRoot = ""; basePath = ""; homePath = ""; lastProfile = "Default" }
    if (Test-Path -LiteralPath $p) {
        try { $j = Get-Content -LiteralPath $p -Raw | ConvertFrom-Json; foreach ($k in $o.PSObject.Properties.Name) { if ($j.$k) { $o.$k = $j.$k } } } catch {}
    }
    $o
}
function Save-GuiSettings($o) { $o | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $DataDir "gui_settings.json") -Encoding UTF8 }

# ======================================================================================================================
# the generated catalogue
# ======================================================================================================================
function Import-Catalogue {
    $cands = @()
    if ($Catalogue) { $cands += $Catalogue }
    $cands += (Join-Path $InstallRoot "hzm_server_settings.json")
    $cands += (Join-Path $PSScriptRoot "hzm_server_settings.json")
    $cands += (Join-Path $PSScriptRoot "..\..\docs\generated\server_settings.json")   # running from the dev tree
    foreach ($c in $cands) {
        if ($c -and (Test-Path -LiteralPath $c)) {
            Add-Type -AssemblyName System.Web.Extensions
            $js = New-Object System.Web.Script.Serialization.JavaScriptSerializer
            $js.MaxJsonLength = 64MB
            $cat = $js.DeserializeObject([IO.File]::ReadAllText((Resolve-Path -LiteralPath $c).Path))
            $cat["_path"] = (Resolve-Path -LiteralPath $c).Path
            $byName = @{}
            foreach ($e in $cat["settings"]) { $byName[$e["name"].ToLower()] = $e }
            $cat["_byName"] = $byName
            return $cat
        }
    }
    throw "hzm_server_settings.json not found beside the GUI - run the MOH Coop Trilogy shortcut once so the updater can fetch it."
}

# ======================================================================================================================
# profiles
# ======================================================================================================================
function New-Profile([string]$name, [int]$port = 12203) {
    [pscustomobject]@{
        name = $name; mode = "dedicated"; hostname = "^3MOH ^7Coop ^2Server"; port = $port; queryPort = $port + 97
        maxPlayers = 4; public = $false; missionMode = "campaign"; map = "m1l1"; rotation = @(); settings = @{}
        affinity = @(); priority = "AboveNormal"; autoRestart = $true; dailyRestart = ""; startWithWindows = $false
        # how start-with-Windows starts it: "hidden" = the supervisor alone (no window), "window" = this window opens on
        # the profile and starts its server. A profile saved before the field existed reads "hidden", as it ran then.
        startupMode = "hidden"
        motd = ""; motdRepeatMin = 0; hookUp = $true; hookDown = $true; hookJoin = $true; hookLeave = $true
        logKeepDays = 14; bans = @(); whitelist = @(); whitelistOn = $false; updateOnStart = $false
        hookLag = $false          # Discord: the server fell badly behind (off by default)
        # mission playlists: named rotations [{ name; maps = @(spec...); shuffle; loop }], and how the rotation runs
        playlists = @(); rotationShuffle = $false; rotationLoop = $true
        lightGraphics = "auto"; upnp = $false
        # match recording: the engine's server recorder (sv_demo.c) - sv_autoRecord = one demo per map, every player
        # and AI on it; the engine keeps sv_autoRecordMax files / sv_autoRecordMaxMB in <home>\maintt\demos
        recordMatches = $true; recordMaxFiles = 30; recordMaxMB = 2048
        recordFolder = ""; recordFolderMaxGB = 20; recordFolderMaxDays = 30
    }
}
function Get-ProfileNames {
    @(Get-ChildItem -LiteralPath (Join-Path $DataDir "profiles") -Filter "*.json" -File -ErrorAction SilentlyContinue |
        ForEach-Object { $_.BaseName } | Sort-Object)
}
function Test-ProfileName([string]$n) { $n -match '^[A-Za-z0-9 _-]{1,32}$' }
function Read-Profile([string]$name) {
    $p = New-Profile $name
    $f = Join-Path $DataDir "profiles\$name.json"
    if (Test-Path -LiteralPath $f) {
        try {
            $j = Get-Content -LiteralPath $f -Raw | ConvertFrom-Json
            foreach ($k in $p.PSObject.Properties.Name) {
                if ($null -ne $j.PSObject.Properties[$k]) { $p.$k = $j.$k }
            }
            $h = @{}
            if ($j.settings) { foreach ($q in $j.settings.PSObject.Properties) { $h[$q.Name] = "$($q.Value)" } }
            $p.settings = $h
            $p.rotation = @($j.rotation | Where-Object { $_ }); $p.affinity = @($j.affinity | ForEach-Object { [int]$_ })
            $p.bans = @($j.bans | Where-Object { $_ }); $p.whitelist = @($j.whitelist | Where-Object { $_ })
            $p.playlists = @($j.playlists | Where-Object { $_ -and $_.name } | ForEach-Object {
                [pscustomobject]@{ name = "$($_.name)"; maps = @($_.maps | Where-Object { $_ }); shuffle = [bool]$_.shuffle; loop = ($null -eq $_.loop -or [bool]$_.loop) } })
        } catch { Write-Log "profile $name unreadable: $_" }
    }
    $p
}
function Save-Profile($p) {
    $p | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $DataDir "profiles\$($p.name).json") -Encoding UTF8
}
function Read-Secrets([string]$name) {
    $o = @{ password = ""; rcon = ""; webhook = "" }
    $f = Join-Path $DataDir "profiles\$name.secret"
    if (Test-Path -LiteralPath $f) {
        $t = Unprotect-Text ((Get-Content -LiteralPath $f -Raw).Trim())
        if ($t) { try { $j = $t | ConvertFrom-Json; foreach ($k in @("password", "rcon", "webhook")) { if ($j.$k) { $o[$k] = "$($j.$k)" } } } catch {} }
    }
    foreach ($k in $o.Keys) { if ($o[$k]) { $script:SecretWords.Add($o[$k]) } }
    $o
}
function Save-Secrets([string]$name, $o) {
    $t = ([pscustomobject]$o | ConvertTo-Json -Compress)
    Set-Content -LiteralPath (Join-Path $DataDir "profiles\$name.secret") -Value (Protect-Text $t) -Encoding ascii
    foreach ($k in @("password", "rcon", "webhook")) { if ($o[$k]) { $script:SecretWords.Add($o[$k]) } }
}

# ======================================================================================================================
# the server config the GUI writes (and the command line)
# ======================================================================================================================
function Get-CleanValue([string]$v) {
    # a cfg value can never break out of its quotes or start a second command
    if ($null -eq $v) { return "" }
    ($v -replace '["\r\n;]', '').Trim()
}
function Test-MapName([string]$m) { $m -match '^[A-Za-z0-9_/]{1,64}$' }
# a mission is a map SPEC: the map plus the start tile's own cvars, "m4l0|coop_advTraining=1" (generated catalogue)
function Split-MapSpec([string]$spec) {
    $parts = "$spec" -split '\|'
    $sets = [ordered]@{}
    foreach ($x in ($parts | Select-Object -Skip 1)) {
        if ($x -match '^([A-Za-z_][A-Za-z0-9_]{0,63})=([A-Za-z0-9_.-]{0,64})$') { $sets[$Matches[1]] = $Matches[2] }
    }
    [pscustomobject]@{ Map = $parts[0]; Sets = $sets }
}
function Test-MapSpec([string]$spec) { Test-MapName (Split-MapSpec $spec).Map }
function Test-CvarName([string]$n) { $n -match '^[A-Za-z_][A-Za-z0-9_]{0,63}$' }

function Get-FirstMap($p, $cat) {
    switch ($p.missionMode) {
        "campaign" { return $cat["campaign"]["lobby_map"] }
        "rotation" { if (@($p.rotation).Count) { return @($p.rotation)[0] } }
    }
    if (Test-MapSpec $p.map) { return $p.map }
    "m1l1"
}

function New-ServerCfgText($p, $sec, $cat, [switch]$Listen, [switch]$LightGraphics) {
    $L = New-Object System.Collections.Generic.List[string]
    $L.Add("// GENERATED by the MOH Coop Server GUI (hzm_server_gui.ps1) for profile '$($p.name)' - rewritten on every start.")
    $L.Add("// Holds this server's passwords: the GUI deletes it once the server has read it.")
    if (-not $Listen) { $L.Add("exec coop_mod/cfg/server_rules.cfg") }
    $L.Add("set sv_hostname `"$(Get-CleanValue $p.hostname)`"")
    $L.Add("set password `"$(Get-CleanValue $sec.password)`"")
    $L.Add("set rconPassword `"$(Get-CleanValue $sec.rcon)`"")
    $L.Add("set sv_gamespy $(if ($p.public) { 1 } else { 0 })")
    $L.Add("set sv_banFile `"hzm_servergui/$($p.name -replace '[^A-Za-z0-9_-]', '_')_bans.dat`"")
    foreach ($k in ($p.settings.Keys | Sort-Object)) {
        if (-not (Test-CvarName $k)) { continue }
        $e = $cat["_byName"][$k.ToLower()]
        if (-not $e) { continue }                                     # a cvar the catalogue no longer has is dropped
        if ($e["page"] -eq "server") { continue }                     # the Server tab owns those
        $L.Add("set $($e["name"]) `"$(Get-CleanValue $p.settings[$k])`"")
    }
    $campaign = if ($p.missionMode -eq "campaign") { 1 } else { 0 }
    $L.Add("set coop_campaign $campaign")
    if (-not $Listen) {
        $L.Add("set sv_autoRecord $(if ($p.recordMatches) { 1 } else { 0 })")
        # 0 = keep all: SVR_Rotate (sv_demo.c) skips a cap that is <= 0; a size cap is at least 50 MB
        $L.Add("set sv_autoRecordMax $([math]::Max(0, [int]$p.recordMaxFiles))")
        $rmb = [int]$p.recordMaxMB; $L.Add("set sv_autoRecordMaxMB $(if ($rmb -le 0) { 0 } else { [math]::Max(50, $rmb) })")
    }
    # bans and whitelist (ioq3 ban list: banaddr / exceptaddr, written to sv_banFile)
    $L.Add("flushbans")
    foreach ($b in @($p.bans)) { $ip = Get-CleanValue $b; if ($ip -match '^[0-9./]+$') { $L.Add("banaddr $ip") } }
    if ($p.whitelistOn -and @($p.whitelist).Count) {
        $L.Add("banaddr 0.0.0.0/0")
        foreach ($w in @($p.whitelist)) { $ip = Get-CleanValue $w; if ($ip -match '^[0-9./]+$') { $L.Add("exceptaddr $ip") } }
        $L.Add("exceptaddr 127.0.0.1")
    }
    $first = Get-FirstMap $p $cat
    if ($Listen) {
        # host-and-play: the coop start screen's own recipe (ui_startdmmap 2 via start_server.cfg / campaign_start.cfg).
        # `wait` lets the UI finish starting: ui_startdmmap is registered by CL_InitializeUI on the first frame.
        $L.Add("set ui_hostname `"$(Get-CleanValue $p.hostname)`"")
        $L.Add("set ui_maxclients $([int]$p.maxPlayers)")
        $L.Add("set sv_maxclients $([int]$p.maxPlayers)")
        $L.Add("set ui_gamespy $(if ($p.public) { 1 } else { 0 })")
        $L.Add("set ui_dedicated 0")
        if ($LightGraphics) { $L.Add("exec coop_mod/cfg/gfx_preset_low.cfg") }
        $L.Add("wait 120")
        if ($campaign) { $L.Add("exec coop_mod/cfg/campaign_start.cfg") }
        else {
            $fs = Split-MapSpec $first
            $L.Add("set ui_dmmap $($fs.Map)"); $L.Add("exec coop_mod/start_server.cfg")
            foreach ($k in $fs.Sets.Keys) { $L.Add("set $k $($fs.Sets[$k])") }    # after start_server.cfg, as the tile does
        }
    } else {
        $fs = Split-MapSpec $first
        foreach ($k in $fs.Sets.Keys) { $L.Add("set $k $($fs.Sets[$k])") }
        $L.Add("map $($fs.Map)")     # `map`, never ui_startdmmap (a client command - dedicated_example.cfg)
    }
    ($L -join "`r`n") + "`r`n"
}

function Get-ProfileTag($p) { $p.name -replace '[^A-Za-z0-9_-]', '_' }
# the address a friend types: the game adds 12203 (PORT_SERVER, NET_StringToAdr) when no port is given
function Get-JoinAddress([string]$ip, [int]$port) { if ($port -eq 12203) { "$ip" } else { "${ip}:$port" } }
# the first port pair (game port + 97 for the browser) from 12203 up that no OTHER profile needs: one that is running now or
# starts with Windows. A saved profile that is never run does not hold its ports (bug-11454: a second profile used to get
# 12204 for good, and friends then had to type :12204)
function Get-FreePort([string]$exceptName = "") {
    $used = @(Get-ProfileNames | Where-Object { $_ -ne $exceptName } | ForEach-Object {
        $o = Read-Profile $_
        if ($o.startWithWindows -or (Test-Running $o)) { [int]$o.port; [int]$o.queryPort }
    })
    $port = 12203; while ($used -contains $port -or $used -contains ($port + 97)) { $port++ }
    $port
}
function Test-PortClash($p) {
    foreach ($n in Get-ProfileNames) {
        if ($n -eq $p.name) { continue }
        $o = Read-Profile $n
        if (-not (Test-Running $o)) { continue }
        if (@($o.port, $o.queryPort) | Where-Object { $_ -eq $p.port -or $_ -eq $p.queryPort }) { return $o.name }
    }
    ""
}
# the UDP port the server really bound, from its console ("Opening IP socket: 0.0.0.0:12204" - one line per try, the
# last one is the bind that held) and whether a strict bind found the port taken (NET_OpenIP, net_portStrict 1)
function Get-BoundPort([string]$text) {
    $r = [pscustomobject]@{ Port = 0; Busy = $false }
    foreach ($m in [regex]::Matches($text, 'Opening IP socket: [^\s:]+:(\d+)')) { $r.Port = [int]$m.Groups[1].Value }
    if ($text -match 'NETPORT busy port=\d+|net_portStrict: UDP port \d+ is already in use') { $r.Busy = $true; $r.Port = 0 }
    $r
}
# the engine's tick-rate lines (sv_main.c SV_TpsLog_Frame, bug-11486)
function Read-TpsLine([string]$ln) {
    if ($ln -match '\^~\^~\^ SVTPS target=([\d.]+) actual=([\d.]+) avg=([\d.]+) max=([\d.]+) gap=(\d+) late=(\d+) dropped=(\d+)') {
        $r = [pscustomobject]@{ Kind = "tps"; Target = [double]$Matches[1]; Actual = [double]$Matches[2]; AvgMs = [double]$Matches[3]
            MaxMs = [double]$Matches[4]; GapMs = [int]$Matches[5]; Late = [int]$Matches[6]; Dropped = [int]$Matches[7]; InKB = -1.0; OutKB = -1.0 }
        if ($ln -match ' in=([\d.]+) out=([\d.]+)') { $r.InKB = [double]$Matches[1]; $r.OutKB = [double]$Matches[2] }   # engine 1.10.91+
        return $r
    }
    if ($ln -match '\^~\^~\^ SVBEHIND behind=(\d+) ticks=(\d+) frame=(\d+)') {
        return [pscustomobject]@{ Kind = "behind"; BehindMs = [int]$Matches[1]; Ticks = [int]$Matches[2]; FrameMs = [int]$Matches[3] }
    }
    if ($ln -match '^Hitch warning: (\d+) msec frame time') { return [pscustomobject]@{ Kind = "hitch"; Ms = [int]$Matches[1] } }
    $null
}
# "badly behind" for the optional Discord notice: under 90 % of the target tick rate, or a frame a second late
function Test-BadLag($t) {
    if (-not $t) { return $false }
    if ($t.Kind -eq "tps") { return ($t.Target -gt 0 -and $t.Actual -lt 0.9 * $t.Target) }
    if ($t.Kind -eq "behind") { return ($t.BehindMs -ge 1000) }
    if ($t.Kind -eq "hitch") { return ($t.Ms -ge 1000) }
    $false
}
# a chat line in the dedicated console: Player::EventDMMessage -> G_PrintfClient -> "{#0 | ip:port} Name says @all: text"
function Read-ChatLine([string]$ln) {
    if ($ln -match '^\{#(\d+) \| [^}]*\} (.+?) (says|shouts) (@all|@team|@#\d+)(?: \(filtered out\))?: (.*)$') {
        return [pscustomobject]@{ Num = [int]$Matches[1]; Name = $Matches[2]; Kind = $Matches[3]; To = $Matches[4]; Text = $Matches[5].TrimEnd() }
    }
    $null
}
# session history: one JSON object per line in logs\<profile>\history.jsonl (join / leave / map), kept logKeepDays
function Get-HistoryPath($p) { Join-Path $DataDir ("logs" + [IO.Path]::DirectorySeparatorChar + (Get-ProfileTag $p) + [IO.Path]::DirectorySeparatorChar + "history.jsonl") }
function Add-History($p, [hashtable]$e) {
    $e["t"] = (Get-Date).ToString("s")
    $f = Get-HistoryPath $p
    $d = Split-Path -Parent $f
    if (-not (Test-Path -LiteralPath $d)) { New-Item -ItemType Directory -Force -Path $d | Out-Null }
    try { Add-Content -LiteralPath $f -Value (([pscustomobject]$e) | ConvertTo-Json -Compress) -Encoding UTF8 } catch {}
}
function Get-History($p) {
    $f = Get-HistoryPath $p
    if (-not (Test-Path -LiteralPath $f)) { return , @() }
    , @(Get-Content -LiteralPath $f -Encoding UTF8 | Where-Object { $_.Trim() } | ForEach-Object { try { $_ | ConvertFrom-Json } catch {} } | Where-Object { $_ })
}
function Limit-History($p) {
    $f = Get-HistoryPath $p
    if (-not (Test-Path -LiteralPath $f)) { return }
    $cut = (Get-Date).AddDays(-[math]::Max(1, [int]$p.logKeepDays))
    $keep = @(Get-Content -LiteralPath $f -Encoding UTF8 | Where-Object { try { [datetime]($_ | ConvertFrom-Json).t -ge $cut } catch { $false } })
    Set-Content -LiteralPath $f -Value $keep -Encoding UTF8
}
function Get-Shuffled($list) { @($list | Sort-Object { Get-Random }) }
function Format-Duration([double]$sec) {
    $t = [TimeSpan]::FromSeconds([math]::Max(0, $sec))
    if ($t.TotalHours -ge 1) { "{0}h {1:00}m" -f [int][math]::Floor($t.TotalHours), $t.Minutes } else { "{0}m {1:00}s" -f $t.Minutes, $t.Seconds }
}
# ---- one-click crash report (bug-11500): dumps, logs and the profile in one zip; secrets never leave this PC ----------
function Get-ReportSecrets($p) {
    $sec = Read-Secrets $p.name
    @(@($sec.password, $sec.rcon, $sec.webhook) | Where-Object { $_ -and $_.Length -ge 3 })
}
function Protect-ReportText([string]$t, [string[]]$secrets) {
    foreach ($w in $secrets) { $t = $t.Replace($w, "<removed>") }
    # anything that still looks like one: a password / rcon cvar value, a Discord webhook URL
    $t = [regex]::Replace($t, '(?im)\b(set[as]?\s+)?(rconPassword|password|sv_privatePassword|g_password)(\s+|\\)("[^"\r\n]*"|\S+)', '$1$2$3<removed>')
    [regex]::Replace($t, 'https://(\w+\.)?discord(app)?\.com/api/webhooks/\S+', '<removed webhook>')
}
function Clear-SecretsInFile([string]$path, [string[]]$secrets) {
    # a full-memory dump can hold the rcon password (the cvar lives in the process): overwrite every ASCII / UTF-16
    # copy of each secret with X before it is zipped
    if (-not $secrets.Count) { return 0 }
    if (-not ("HzmScrub" -as [type])) {
        Add-Type -TypeDefinition @"
public static class HzmScrub {
    public static int Wipe(byte[] buf, byte[] pat) {
        int n = 0;
        if (pat.Length == 0) return 0;
        for (int i = 0; i + pat.Length <= buf.Length; i++) {
            int j = 0;
            while (j < pat.Length && buf[i + j] == pat[j]) j++;
            if (j == pat.Length) { for (int k = 0; k < pat.Length; k++) buf[i + k] = (byte)'X'; n++; i += pat.Length - 1; }
        }
        return n;
    }
}
"@
    }
    $b = [IO.File]::ReadAllBytes($path); $n = 0
    foreach ($w in $secrets) {
        $n += [HzmScrub]::Wipe($b, [Text.Encoding]::ASCII.GetBytes($w))
        $n += [HzmScrub]::Wipe($b, [Text.Encoding]::Unicode.GetBytes($w))
    }
    if ($n) { [IO.File]::WriteAllBytes($path, $b) }
    $n
}
function Export-CrashReport($p, $inst, [string]$outDir = [Environment]::GetFolderPath("MyDocuments")) {
    $tag = Get-ProfileTag $p
    $stamp = Get-Date -Format "yyyy-MM-dd_HHmm"
    $work = Join-Path $env:TEMP "mohcoop_report_$tag_$stamp"
    Remove-Item -LiteralPath $work -Recurse -Force -ErrorAction SilentlyContinue
    New-Item -ItemType Directory -Force -Path $work | Out-Null
    $secrets = Get-ReportSecrets $p
    $notes = New-Object System.Collections.Generic.List[string]
    $notes.Add("MOH Coop Server crash report - profile '$($p.name)' - $(Get-Date -Format s)")
    $notes.Add("Passwords, the rcon password and the Discord webhook were removed from every file (logs, profile, dumps).")
    # the newest crash dumps of the game and of the server (Windows Error Reporting), last 7 days, two of each
    $dd = Join-Path $env:LOCALAPPDATA "CrashDumps"
    foreach ($exe in @("openmohaa.exe", "omohaaded.exe")) {
        foreach ($f in @(Get-ChildItem -LiteralPath $dd -Filter "$exe.*.dmp" -File -ErrorAction SilentlyContinue |
                Where-Object { $_.LastWriteTime -gt (Get-Date).AddDays(-7) } | Sort-Object LastWriteTime -Descending | Select-Object -First 2)) {
            $dst = Join-Path $work ("dumps_" + $f.Name)
            Copy-Item -LiteralPath $f.FullName -Destination $dst
            $w = Clear-SecretsInFile $dst $secrets
            $notes.Add("dump $($f.Name) ($([math]::Round($f.Length / 1MB)) MB, $($f.LastWriteTime))$(if ($w) { " - $w secret copies overwritten" })")
        }
    }
    $texts = New-Object System.Collections.Generic.List[object]
    foreach ($f in @((Join-Path $inst.Root "hzm_fatal.log"), (Join-Path $inst.Maintt "qconsole.log"), (Join-Path $inst.Root "updater.log"))) {
        if (Test-Path -LiteralPath $f) { $texts.Add([pscustomobject]@{ Src = $f; Name = (Split-Path -Leaf $f) }) }
    }
    $ld = Join-Path $DataDir "logs\$tag"
    foreach ($f in @(Get-ChildItem -LiteralPath $ld -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -match '^(supervisor\.log|history\.jsonl)$' })) { $texts.Add([pscustomobject]@{ Src = $f.FullName; Name = "server_" + $f.Name }) }
    foreach ($f in @(Get-ChildItem -LiteralPath $ld -Filter "server_*.log*" -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 4)) { $texts.Add([pscustomobject]@{ Src = $f.FullName; Name = "server_" + $f.Name }) }
    foreach ($f in @(Get-ChildItem -LiteralPath $ld -Filter "lag_*.log" -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 2)) { $texts.Add([pscustomobject]@{ Src = $f.FullName; Name = "server_" + $f.Name }) }
    $pf = Join-Path $DataDir "profiles\$($p.name).json"
    if (Test-Path -LiteralPath $pf) { $texts.Add([pscustomobject]@{ Src = $pf; Name = "profile_$tag.json" }) }      # never the .secret file
    foreach ($t in $texts) {
        try {
            $raw = [IO.File]::ReadAllText($t.Src, [Text.Encoding]::GetEncoding(28591))
            if ($raw.Length -gt 8MB) { $raw = $raw.Substring($raw.Length - 8MB) }
            [IO.File]::WriteAllText((Join-Path $work $t.Name), (Protect-ReportText $raw $secrets), [Text.Encoding]::GetEncoding(28591))
            $notes.Add("file $($t.Name)")
        } catch { $notes.Add("skipped $($t.Name): $_") }
    }
    [IO.File]::WriteAllLines((Join-Path $work "README.txt"), [string[]]$notes)
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    $zip = Join-Path $outDir ("MOH Coop crash report - {0} - {1}.zip" -f $tag, $stamp)
    Remove-Item -LiteralPath $zip -Force -ErrorAction SilentlyContinue
    [IO.Compression.ZipFile]::CreateFromDirectory($work, $zip, [IO.Compression.CompressionLevel]::Optimal, $false)
    Remove-Item -LiteralPath $work -Recurse -Force -ErrorAction SilentlyContinue
    $zip
}

# ---- "can my friends reach me?" (bug-11501): what can honestly be told from this PC alone ---------------------------
function Test-Reach([int]$port, [string]$publicIp, [bool]$firewallRule) {
    $r = [ordered]@{ Verdict = ""; Detail = ""; Share = "" }
    $local = Send-Oob "getinfo reach" $port "127.0.0.1" 1500
    if (-not $local) { $r.Verdict = "Can't tell"; $r.Detail = "The server is not answering on this PC (port $port). Start it first."; return [pscustomobject]$r }
    if (-not $publicIp) { $r.Verdict = "Can't tell"; $r.Detail = "Your public IP could not be fetched (no internet, or api.ipify.org blocked)."; return [pscustomobject]$r }
    $r.Share = Get-JoinAddress $publicIp $port
    $pub = Send-Oob "getinfo reach" $port $publicIp 2500
    if ($pub) {
        $r.Verdict = "Open"
        $r.Detail = "Your router answered for $($r.Share) and passed the query to this server, so friends can join at $($r.Share)."
    } else {
        $r.Verdict = "Can't tell"
        $why = "Asking your own public address from inside your network only works when the router supports it (NAT loopback), and many do not - so no answer does not prove it is closed."
        if (-not $firewallRule) { $why += " Windows Firewall has no rule for this server yet: add one (above) - that alone blocks friends." }
        $why += " To be sure, ask a friend to join $($r.Share). If that fails, forward UDP $port (and $($port + 97) for the server list) on your router to this PC, or use UPnP above."
        $r.Detail = $why
    }
    [pscustomobject]$r
}

# ---- demo library (bug-11502) -------------------------------------------------------------------------------------
function Read-DemoInfo([string]$dmi) {
    $kv = @{}
    try { $f = ([IO.File]::ReadAllText($dmi)).Split('\'); for ($i = 1; $i + 1 -lt $f.Count; $i += 2) { $kv[$f[$i]] = $f[$i + 1] } } catch {}
    $kv
}
function Get-DemoList($p, $inst) {
    $out = New-Object System.Collections.Generic.List[object]
    $dirs = @([pscustomobject]@{ Dir = (Join-Path $inst.Maintt "demos"); Where = "server" })
    if ($p.recordFolder) { $dirs += [pscustomobject]@{ Dir = $p.recordFolder; Where = "copy folder" } }
    foreach ($d in $dirs) {
        foreach ($f in @(Get-ChildItem -LiteralPath $d.Dir -Filter "*.dm_*" -File -ErrorAction SilentlyContinue)) {
            $base = [IO.Path]::GetFileNameWithoutExtension($f.Name)
            $kv = Read-DemoInfo (Join-Path $d.Dir "$base.dmi")
            $len = 0; [void][int]::TryParse("$($kv['length'])", [ref]$len)
            $out.Add([pscustomobject]@{
                Map = if ($kv['maps']) { $kv['maps'] } else { ($base -replace '^(auto|replay|server)_\d{4}-\d\d-\d\d_\d\d-\d\d-\d\d_', '') }
                Date = $f.LastWriteTime.ToString("yyyy-MM-dd HH:mm"); Length = $(if ($len) { Format-Duration $len } else { "" })
                Size = "{0:0.0} MB" -f ($f.Length / 1MB); Players = "$($kv['players'])"; Where = $d.Where
                Path = $f.FullName; Base = $base; Folder = $d.Dir })
        }
    }
    , @($out | Sort-Object Date -Descending)
}
function Get-DemoFiles([string]$path) {
    # a demo and the files that belong to it: .dmi info, .animtab, .jpg thumbnail
    $dir = Split-Path -Parent $path; $base = [IO.Path]::GetFileNameWithoutExtension($path)
    @(Get-ChildItem -LiteralPath $dir -File -ErrorAction SilentlyContinue | Where-Object { [IO.Path]::GetFileNameWithoutExtension($_.Name) -eq $base } | ForEach-Object { $_.FullName })
}

# ---- start-list groups (bug-11497): chapters, a game's whole campaign, the Chronological Campaign -------------------
# all from the generated catalogue: boards = the mod's own campaign menus (ui/coop_start), games / chrono = its
# campaign_games overlay and coop_mod/chrono.scr::nextMission. A disc board shows only when this PC converted the disc.
function Get-StartGroups($cat, $byo) {
    $boards = @{}; $groups = New-Object System.Collections.Generic.List[object]
    foreach ($b in $cat["missions"]) {
        $maps = @($b["maps"] | Where-Object { -not $_["byo"] -or $byo.ContainsKey($_["map"]) } | ForEach-Object { $_["spec"] })
        if (-not $maps.Count) { continue }
        $boards[$b["board"]] = $maps
        $groups.Add([pscustomobject]@{ Name = "Chapter: " + $b["title"]; Maps = $maps })
    }
    foreach ($g in @($cat["campaign"]["games"])) {
        if (-not $g) { continue }
        $m = @($g["boards"] | Where-Object { $boards.ContainsKey($_) } | ForEach-Object { $boards[$_] })
        if ($m.Count) { $groups.Add([pscustomobject]@{ Name = "Entire campaign: " + $g["name"]; Maps = $m }) }
    }
    $ch = @($cat["campaign"]["chrono"])
    if ($ch.Count) {
        $m = @($ch | Where-Object { $boards.ContainsKey($_) } | ForEach-Object { $boards[$_] })
        if ($m.Count) { $groups.Add([pscustomobject]@{ Name = "Chronological order (all three games, the mod's Chronological Campaign)"; Maps = $m }) }
    }
    , $groups.ToArray()
}
function Get-PortNote([int]$want, [int]$got) {
    "UDP $want was busy (probably the game is open on this PC), so the server took $got. Friends must type :$got after " +
    "the address, and firewall/router rules made for $want do not cover it. Close the game and restart the server to get $want back."
}

function Get-DedicatedArgs($p, $inst) {
    $tag = Get-ProfileTag $p
    # g_gametype MUST be on the command line (latched); every value quoted; under Com_ParseCommandLine's 32-line cap
    @('+set', 'dedicated', '1', '+set', 'com_target_game', '2', '+set', 'g_gametype', '2',
      '+set', 'fs_basepath', "`"$($inst.Base)`"", '+set', 'fs_homepath', "`"$($inst.Home)`"",
      '+set', 'config', "hzm_server_$tag.cfg", '+set', 'logfile', '0',
      '+set', 'net_port', "$([int]$p.port)", '+set', 'net_gamespy_port', "$([int]$p.queryPort)",
      '+set', 'sv_maxclients', "$([int]$p.maxPlayers)", '+set', 'com_abnormalExit', '0',
      # bind net_port exactly or stop (bug-11450): stock ioq3 silently moves to +1..+9 when the port is taken - the
      # game's own client socket holds 12203 while it is open - and friends joining by IP alone then reach nothing
      '+set', 'net_portStrict', '1',
      # tick-rate log (bug-11486): SVTPS every 10 s for the Status graph, SVBEHIND when a frame is a tick late
      '+set', 'sv_tpsLog', '1', '+set', 'sv_tpsLogInterval', '10',
      '+exec', "hzm_servergui/$tag.cfg")
}

function Get-ListenArgs($p, $inst, [switch]$LightGraphics) {
    $tag = Get-ProfileTag $p
    $a = $inst.LaunchArgs
    if (-not $a) { $a = "+set fs_basepath `"$($inst.Base)`" +set fs_homepath `"$($inst.Home)`" +set com_target_game 2" }
    if ($LightGraphics) { $a = ($a -replace '\+set cl_renderer \S+', '') + " +set cl_renderer opengl1" }
    elseif ($a -notmatch 'cl_renderer') { $a += " +set cl_renderer opengl2" }
    $a + " +set net_port $([int]$p.port) +set coop_reportLauncher servergui +exec hzm_servergui/${tag}_listen.cfg"
}

function Write-ServerCfg($p, $sec, $cat, $inst, [switch]$Listen, [switch]$LightGraphics) {
    $dir = Join-Path $inst.Maintt "hzm_servergui"
    if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
    $tag = Get-ProfileTag $p
    $f = if ($Listen) { Join-Path $dir "${tag}_listen.cfg" } else { Join-Path $dir "$tag.cfg" }
    [IO.File]::WriteAllText($f, (New-ServerCfgText $p $sec $cat -Listen:$Listen -LightGraphics:$LightGraphics), (New-Object Text.ASCIIEncoding))
    # the profile's own saved server config would carry a reset setting forward (archived cvars are written at exit,
    # TRAPS T7): start every boot from the shipped defaults + this cfg
    if (-not $Listen) { Remove-Item -LiteralPath (Join-Path $inst.Maintt "configs\hzm_server_$tag.cfg") -Force -ErrorAction SilentlyContinue }
    $f
}

