            <Button x:Name="btnRescan" Content="Scan again"/>
            <Button x:Name="btnSpeed" Content="Test upload speed (optional)"/>
            <TextBlock x:Name="txtSpeedNote" Foreground="{StaticResource Muted}" Text="Sends 4 MB of random data to a speed-test server. Only when you click."/>
          </StackPanel>
          <GroupBox Header="Processor"><TextBlock x:Name="txtCpu" FontFamily="Consolas"/></GroupBox>
          <GroupBox Header="Memory, graphics and disk"><TextBlock x:Name="txtSys" FontFamily="Consolas"/></GroupBox>
          <GroupBox Header="Suggestion"><TextBlock x:Name="txtSuggestion"/></GroupBox>
        </StackPanel></ScrollViewer>
      </TabItem>

      <TabItem Header="Advanced">
        <TabControl x:Name="advTabs" Background="#FF1E1F1A" BorderBrush="{StaticResource Edge}" Margin="6">
          <TabItem Header="CPU">
            <ScrollViewer VerticalScrollBarVisibility="Auto"><StackPanel Margin="10">
              <TextBlock x:Name="txtAffHelp" Foreground="{StaticResource Muted}" Margin="0,0,0,6"/>
              <StackPanel Orientation="Horizontal">
                <Button x:Name="btnAffRecommend" Content="Use the recommended thread"/>
                <Button x:Name="btnAffAll" Content="Any thread (Windows decides)"/>
