              </StackPanel>
              <WrapPanel x:Name="wpAffinity" Margin="0,8"/>
              <StackPanel Orientation="Horizontal" Margin="0,6">
                <TextBlock Text="Process priority  " />
                <ComboBox x:Name="cbPriority" Width="160"/>
              </StackPanel>
            </StackPanel></ScrollViewer>
          </TabItem>
          <TabItem Header="Server tuning">
            <ScrollViewer VerticalScrollBarVisibility="Auto"><StackPanel x:Name="spTuning" Margin="10"/></ScrollViewer>
          </TabItem>
          <TabItem Header="Network">
            <ScrollViewer VerticalScrollBarVisibility="Auto"><StackPanel Margin="10">
