              </StackPanel></GroupBox>
              <GroupBox Header="Let players reach you"><StackPanel>
                <TextBlock Foreground="{StaticResource Muted}" Text="Both actions change your PC or router, so each one asks you first, every time. Players on your own network need neither."/>
                <StackPanel Orientation="Horizontal" Margin="0,6,0,0">
                  <Button x:Name="btnFirewall" Content="Add Windows Firewall rule..."/>
