                <StackPanel Grid.Column="2"><CheckBox x:Name="cbWhitelist" Content="Whitelist only (everyone else is refused)"/><TextBox x:Name="tbWhitelist" AcceptsReturn="True" Height="70" VerticalScrollBarVisibility="Auto"/></StackPanel>
              </Grid></GroupBox>
              <GroupBox Header="Discord webhook"><StackPanel>
                <TextBlock Foreground="{StaticResource Muted}" Text="Paste a channel webhook URL (Server Settings - Integrations - Webhooks). Stored encrypted on this PC for your Windows account only, never written to a log."/>
                <PasswordBox x:Name="pwWebhook"/>
